/** List the events recorded for a Sentry issue, newest first. */
sdk.sentry.listIssueEvents(args: { issueId: string }): Promise<{ events: { id: string; issueId: string; timestamp: string; release: string; message: string }[] }>

/** List the issues of a Sentry project. */
sdk.sentry.listIssues(args: { project: string }): Promise<{ issues: { id: string; shortId: string; project: string; title: string; culprit: string; filename: string; lineNumber: number; level: "fatal" | "error" | "warning" | "info"; status: "unresolved" | "resolved" | "ignored"; count: number; userCount: number; firstSeen: string; lastSeen: string }[] }>

/** List the Sentry projects of the organization. */
sdk.sentry.listProjects(args?: { platform?: string }): Promise<unknown>

/** Get the members of a Sentry project's team. */
sdk.sentry.getProjectTeam(args: { slug: string }): Promise<unknown>

/** Get one Sentry issue by its id. */
sdk.sentry.getIssue(args: { id: string }): Promise<{ id: string; shortId: string; project: string; title: string; culprit: string; filename: string; lineNumber: number; level: "fatal" | "error" | "warning" | "info"; status: "unresolved" | "resolved" | "ignored"; count: number; userCount: number; firstSeen: string; lastSeen: string }>

/** Search Linear issues whose title or description contains the query. */
sdk.linear.searchIssues(args: { query: string }): Promise<{ issues: { id: string; identifier: string; title: string; description: string; assigneeEmail: string | null; state: "Todo" | "In Progress" | "Done" }[] }>

/** Create a Linear issue. Write Tool: a run records this call in its Write Plan instead of sending it, and gets a Placeholder back. */
sdk.linear.createIssue(args: { title: string; description?: string; assigneeEmail?: string }): Promise<Placeholder<{ id: string; identifier: string; title: string; url: string }>>

