{"code": "export async function main(input) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  return issues.map(i => ({ shortId: i.shortId, count: i.count, status: i.status, id: i.id }));
}"}

{"code": "export async function main(input: {}) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const out = [] as { shortId: string; count: number; status: string; latestRelease: string | null }[];
  for (const i of issues) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    const latestRelease = events.length > 0 ? events[0].release : null;
    out.push({ shortId: i.shortId, count: i.count, status: i.status, latestRelease });
  }
  out.sort((a, b) => b.count - a.count);
  return out;
}"}

{"code": "export async function main(input: {}) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const out = [] as any[];
  for (const i of issues) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    out.push({ shortId: i.shortId, count: i.count, n: events.length, first: events[0] ?? null, last: events[events.length - 1] ?? null });
  }
  return out;
}"}

{"code": "export async function main(input: {}) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const out: { shortId: string; count: number; status: string; latestRelease: string | null }[] = [];
  for (const i of issues) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    let newest: { timestamp: string; release: string } | null = null;
    for (const e of events) {
      if (newest === null || new Date(e.timestamp).getTime() > new Date(newest.timestamp).getTime()) {
        newest = { timestamp: e.timestamp, release: e.release };
      }
    }
    out.push({ shortId: i.shortId, count: i.count, status: i.status, latestRelease: newest === null ? null : newest.release });
  }
  out.sort((a, b) => b.count - a.count);
  return out;
}"}
